import React, { useState, useEffect } from "react";
import { View, FlatList, Text, TouchableOpacity } from "react-native";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { Nota } from "./src/componentes/Nota";
import NotaEditor from "./src/componentes/NotaEditor";


export default function App() {
  const [notas, setNotas] = useState([]);
  const [notaEditando, setNotaEditando] = useState(null);

  // Carrega notas do AsyncStorage apenas uma vez ao iniciar
  useEffect(() => {
    carregarNotasIniciais();
  }, []);

  const carregarNotasIniciais = async () => {
    try {
      const todasChaves = await AsyncStorage.getAllKeys();
      const todasNotas = await AsyncStorage.multiGet(todasChaves);

      const notasCarregadas = todasNotas
        .filter(([chave, valor]) => valor && valor.trim() !== "")
        .map(([chave, valor]) => {
          try {
            const notaParseada = JSON.parse(valor);
            return {
              id: chave,
              texto: notaParseada.texto,
              categoria: notaParseada.categoria || "Pessoal"
            };
          } catch (e) {
            return {
              id: chave,
              texto: valor,
              categoria: "Pessoal"
            };
          }
        });

      setNotas(notasCarregadas);
      console.log("Notas carregadas:", notasCarregadas.length);
    } catch (error) {
      console.error("Erro ao carregar notas:", error);
    }
  };

  // Salva uma nota individual
  const salvarNotaStorage = async (nota) => {
    try {
      const notaParaSalvar = {
        texto: nota.texto,
        categoria: nota.categoria
      };
      await AsyncStorage.setItem(nota.id, JSON.stringify(notaParaSalvar));
      return true;
    } catch (error) {
      console.error("Erro ao salvar no storage:", error);
      return false;
    }
  };

  // Remove uma nota do storage
  const removerNotaStorage = async (id) => {
    try {
      await AsyncStorage.removeItem(id);
      console.log("✅ Nota removida do storage:", id);
      return true;
    } catch (error) {
      console.error("❌ Erro ao remover do storage:", error);
      return false;
    }
  };

  const adicionarNota = async (texto, categoria) => {
    const novaNota = {
      id: Date.now().toString(),
      texto: texto,
      categoria: categoria
    };

    const salvo = await salvarNotaStorage(novaNota);
    if (salvo) {
      setNotas(prev => [...prev, novaNota]);
      return true;
    }
    return false;
  };

  const atualizarNota = async (id, texto, categoria) => {
    const notaAtualizada = {
      id: id,
      texto: texto,
      categoria: categoria
    };

    const salvo = await salvarNotaStorage(notaAtualizada);
    if (salvo) {
      setNotas(prev => prev.map(nota => 
        nota.id === id ? notaAtualizada : nota
      ));
      return true;
    }
    return false;
  };

  const excluirNota = async (id) => {
    console.log("Tentando excluir nota ID:", id);

    // Remove do estado local primeiro
    setNotas(prev => {
      const novasNotas = prev.filter(nota => nota.id !== id);
      console.log("Estado local atualizado. Notas restantes:", novasNotas.length);
      return novasNotas;
    });

    // Depois tenta remover do storage
    const removido = await removerNotaStorage(id);
    if (!removido) {
      console.log("⚠️ Não foi possível remover do storage, mas foi removido localmente");
    }

    return true;
  };

  const editarNota = (nota) => {
    setNotaEditando(nota);
  };

  const cancelarEdicao = () => {
    setNotaEditando(null);
  };

  // Função para limpar TUDO - debug
  const limparTudo = async () => {
    Alert.alert(
      "Limpar Tudo",
      "Isso vai apagar TODAS as notas permanentemente. Continuar?",
      [
        { text: "Cancelar", style: "cancel" },
        { 
          text: "SIM, Limpar Tudo", 
          style: "destructive",
          onPress: async () => {
            try {
              const todasChaves = await AsyncStorage.getAllKeys();
              console.log("Removendo chaves:", todasChaves);
              await AsyncStorage.multiRemove(todasChaves);
              setNotas([]);
              console.log("✅ Tudo limpo!");
              Alert.alert("Sucesso", "Todas as notas foram removidas!");
            } catch (error) {
              console.error("Erro ao limpar:", error);
            }
          }
        }
      ]
    );
  };

  return (
    <View style={{ flex: 1, paddingTop: 50 }}>
      <Text style={{ fontSize: 24, fontWeight: "bold", textAlign: "center", marginBottom: 10 }}>
        Minhas Notas
      </Text>
      <Text style={{ textAlign: "center", marginBottom: 20, color: "#666" }}>
        {notas.length} nota(s)
      </Text>

      {/* Botão de debug */}
      <TouchableOpacity 
        style={{
          backgroundColor: "#ff4444",
          padding: 10,
          margin: 16,
          borderRadius: 5,
          alignItems: "center"
        }}
        onPress={limparTudo}
      >
        <Text style={{ color: "white", fontWeight: "bold" }}>
          🗑️ LIMPAR TUDO (Debug)
        </Text>
      </TouchableOpacity>

      <FlatList
        data={notas}
        keyExtractor={(item) => item.id}
        renderItem={({ item }) => (
          <Nota 
            item={item} 
            onPress={() => editarNota(item)}
          />
        )}
        ListEmptyComponent={
          <Text style={{ textAlign: "center", marginTop: 20, padding: 16, color: "#666" }}>
            Nenhuma nota encontrada. Clique no + para criar uma nova nota.
          </Text>
        }
      />

      <NotaEditor 
        onSalvarNota={adicionarNota}
        onAtualizarNota={atualizarNota}
        onExcluirNota={excluirNota}
        notaEditando={notaEditando}
        onCancelarEdicao={cancelarEdicao}
      />
    </View>
  );
}
